/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import { RockOrGasScreen } from "../../src/composition/RockOrGasScreen.js";
import { DimmingScreen } from "../../src/dimming/DimmingScreen.js";
import { PlanetHuntScreen } from "../../src/hunt/PlanetHuntScreen.js";
import { StringManager } from "../../src/i18n/StringManager.js";
import { LightCurveScreen } from "../../src/light-curve/LightCurveScreen.js";
import { LiningUpScreen } from "../../src/lining-up/LiningUpScreen.js";
import TransitHunterColors from "../../src/TransitHunterColors.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();

  const screens = [
    new DimmingScreen({
      name: stringManager.getScreenNames().dimmingStringProperty,
      tandem: Tandem.ROOT.createTandem("dimmingScreen"),
      backgroundColorProperty: TransitHunterColors.backgroundColorProperty,
    }),
    new LiningUpScreen({
      name: stringManager.getScreenNames().liningUpStringProperty,
      tandem: Tandem.ROOT.createTandem("liningUpScreen"),
      backgroundColorProperty: TransitHunterColors.backgroundColorProperty,
    }),
    new LightCurveScreen({
      name: stringManager.getScreenNames().lightCurveStringProperty,
      tandem: Tandem.ROOT.createTandem("lightCurveScreen"),
      backgroundColorProperty: TransitHunterColors.backgroundColorProperty,
    }),
    new PlanetHuntScreen({
      name: stringManager.getScreenNames().huntStringProperty,
      tandem: Tandem.ROOT.createTandem("huntScreen"),
      backgroundColorProperty: TransitHunterColors.backgroundColorProperty,
    }),
    new RockOrGasScreen({
      name: stringManager.getScreenNames().compositionStringProperty,
      tandem: Tandem.ROOT.createTandem("compositionScreen"),
      backgroundColorProperty: TransitHunterColors.backgroundColorProperty,
    }),
  ];

  return { screens, tracked: { TransitHunterColors, stringManager } };
}

let built: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    built = buildSim();
    return built.screens;
  },
  tracked: () => built?.tracked ?? {},
});
